/*
 * Address rules for every country, built on Google's address metadata
 * (address-data.json, generated by shop/scripts/build-address-data.py).
 * Pure functions: no DOM, so tests can run it in Node.
 */
(function (root, factory) {
  if (typeof module === "object" && module.exports) module.exports = factory();
  else root.AddressRules = factory();
})(typeof self !== "undefined" ? self : this, function () {
  "use strict";

  var POSTAL_LABELS = { zip: "ZIP code", postal: "Postal code", pin: "PIN code", eircode: "Eircode" };
  var REGION_LABELS = {
    state: "State", province: "Province", county: "County", prefecture: "Prefecture",
    area: "Area", district: "District", department: "Department", island: "Island",
    emirate: "Emirate", parish: "Parish", do_si: "Province", oblast: "Region"
  };
  var CITY_LABELS = { city: "City", district: "District", post_town: "Town or city", suburb: "Suburb" };
  var SUBLOCALITY_LABELS = {
    suburb: "Suburb", district: "District", neighborhood: "Neighborhood",
    village_township: "Village or township", townland: "Townland"
  };
  // fmt token -> our field key. %N (name) and %O (organization) are asked for
  // separately, %X (sorting code) is rare and left out.
  var TOKENS = { A: "address1", D: "sublocality", C: "city", S: "region", Z: "postal" };
  var REQUIRE_KEYS = { A: "address1", D: "sublocality", C: "city", S: "region", Z: "postal" };

  function titleCase(s) {
    return String(s).toLowerCase().replace(/(^|[\s\-(])([a-z])/g, function (m, a, b) { return a + b.toUpperCase(); });
  }

  function normalizePostal(v) {
    return String(v || "").trim().toUpperCase().replace(/\s+/g, " ");
  }

  function create(data) {
    function country(cc) { return data[cc] || null; }

    function countryName(cc, displayNames) {
      try { if (displayNames) { var n = displayNames.of(cc); if (n && n !== cc) return n; } } catch (e) {}
      var c = data[cc];
      return c ? titleCase(c.name) : cc;
    }

    function countryList(locale, first) {
      var dn = null;
      try { dn = new Intl.DisplayNames([locale || "en"], { type: "region" }); } catch (e) {}
      var list = Object.keys(data).map(function (cc) { return { code: cc, name: countryName(cc, dn) }; });
      list.sort(function (a, b) { return a.name.localeCompare(b.name); });
      if (first) {
        var i = list.findIndex(function (c) { return c.code === first; });
        if (i > 0) list.unshift(list.splice(i, 1)[0]);
      }
      return list;
    }

    // Rows of fields in the order this country writes addresses.
    function layout(cc) {
      var c = country(cc) || {};
      var fmt = c.fmt || "%N%n%O%n%A%n%C";
      var req = c.require || "AC";
      var rows = [];
      fmt.split("%n").forEach(function (line) {
        var row = [];
        (line.match(/%[A-Z]/g) || []).forEach(function (t) {
          var key = TOKENS[t[1]];
          if (!key) return;
          if (key === "address1") {
            rows.push([field(c, "address1", req)]);
            rows.push([field(c, "address2", req)]);
            return;
          }
          row.push(field(c, key, req));
        });
        if (row.length) rows.push(row);
      });
      return rows;
    }

    function field(c, key, req) {
      var letter = Object.keys(REQUIRE_KEYS).find(function (k) { return REQUIRE_KEYS[k] === key; });
      var f = { key: key, required: !!letter && req.indexOf(letter) !== -1 };
      if (key === "address1") { f.label = "Street address"; f.autocomplete = "address-line1"; f.placeholder = "House number and street"; }
      if (key === "address2") { f.label = "Apartment, suite, unit"; f.autocomplete = "address-line2"; f.required = false; }
      if (key === "city") { f.label = CITY_LABELS[c.locality_name_type] || "City"; f.autocomplete = "address-level2"; }
      if (key === "sublocality") { f.label = SUBLOCALITY_LABELS[c.sublocality_name_type] || "Suburb"; f.autocomplete = "address-level3"; }
      if (key === "region") {
        f.label = REGION_LABELS[c.state_name_type] || "State or province";
        f.autocomplete = "address-level1";
        if (c.regions && c.regions.length) f.options = c.regions.map(function (r) { return { value: r.k, label: r.n }; });
      }
      if (key === "postal") {
        f.label = POSTAL_LABELS[c.zip_name_type] || "Postal code";
        f.autocomplete = "postal-code";
        if (c.zipex) f.placeholder = "e.g. " + c.zipex.split(",")[0];
        f.inputmode = /^[\\d\s\-()?{}|,0-9]*$/.test(String(c.zip || "").replace(/\\d/g, "")) && c.zip ? "numeric" : "text";
      }
      return f;
    }

    function regionFor(cc, value) {
      var c = country(cc);
      if (!c || !c.regions) return null;
      var v = String(value || "").trim().toLowerCase();
      return c.regions.find(function (r) { return r.k.toLowerCase() === v || r.n.toLowerCase() === v; }) || null;
    }

    // Returns { errors: {field: message}, address: normalized values }.
    function validate(cc, values) {
      var errors = {};
      var c = country(cc);
      if (!c) return { errors: { country: "Choose a country." }, address: {} };
      var a = {};
      ["address1", "address2", "sublocality", "city", "region", "postal"].forEach(function (k) {
        a[k] = String(values[k] || "").trim().replace(/\s+/g, " ");
      });
      a.postal = normalizePostal(a.postal);
      a.country = cc;

      var fields = {};
      layout(cc).forEach(function (row) { row.forEach(function (f) { fields[f.key] = f; }); });

      Object.keys(fields).forEach(function (k) {
        var f = fields[k];
        if (f.required && !a[k]) errors[k] = "Enter your " + f.label.toLowerCase() + ".";
        if (a[k].length > 120) errors[k] = "That's too long. Keep it under 120 characters.";
      });
      // Fields this country doesn't use are dropped, so stale input from a
      // previously chosen country never ships.
      Object.keys(a).forEach(function (k) { if (k !== "country" && !fields[k]) a[k] = ""; });

      if (a.address1 && !/[\p{L}\p{N}]{2,}/u.test(a.address1)) errors.address1 = "Enter a full street address.";

      var region = null;
      if (fields.region && a.region) {
        if (c.regions && c.regions.length) {
          region = regionFor(cc, a.region);
          if (!region) errors.region = "Choose your " + fields.region.label.toLowerCase() + " from the list.";
          else { a.region = region.k; a.regionName = region.n; }
        } else {
          a.regionName = a.region;
        }
      }

      if (fields.postal && a.postal && c.zip) {
        var re = new RegExp("^(?:" + c.zip + ")$", "i");
        if (!re.test(a.postal)) {
          errors.postal = "That doesn't look like a " + fields.postal.label.replace(/ code$/, "").toLowerCase() +
            " code for this country" + (c.zipex ? " (e.g. " + c.zipex.split(",")[0] + ")." : ".");
          if (fields.postal.label === "Eircode") errors.postal = "That doesn't look like an Eircode (e.g. " + c.zipex.split(",")[0] + ").";
        } else if (region && region.z && !errors.region) {
          var rz = new RegExp("^(?:" + region.z + ")", "i");
          if (!rz.test(a.postal)) errors.postal = "That " + fields.postal.label.replace(/ code$/, "") + " code isn't in " + region.n + ". Check both.";
        }
      }
      return { errors: errors, address: a };
    }

    // Multi-line address in the country's own order, for summaries and labels.
    function format(addr, name) {
      var c = country(addr.country) || {};
      var fmt = c.fmt || "%N%n%O%n%A%n%C";
      var vals = {
        N: name || "", O: "",
        A: [addr.address1, addr.address2].filter(Boolean).join("\n"),
        D: addr.sublocality || "", C: addr.city || "",
        S: (/^[A-Z0-9]{1,3}$/.test(addr.region || "") ? addr.region : addr.regionName || addr.region || ""), Z: addr.postal || "", X: ""
      };
      var lines = fmt.split("%n").map(function (line) {
        return line.replace(/%([A-Z])/g, function (m, t) { return vals[t] || ""; }).replace(/\s+,/g, ",").replace(/^[\s,]+|[\s,]+$/g, "");
      });
      var out = lines.join("\n").split("\n").filter(function (l) { return l.trim(); });
      out.push(countryName(addr.country, (function () { try { return new Intl.DisplayNames(["en"], { type: "region" }); } catch (e) { return null; } })()));
      return out.join("\n");
    }

    return { country: country, countryList: countryList, countryName: countryName, layout: layout, validate: validate, format: format, regionFor: regionFor };
  }

  return { create: create, normalizePostal: normalizePostal };
});
